package com.bank;import java.sql.*;import java.io.*;import java.util.*;public final class DBConnection{public static Connection get()throws SQLException{try(InputStream in=DBConnection.class.getClassLoader().getResourceAsStream("application.properties")){Properties p=new Properties();p.load(in);return DriverManager.getConnection(p.getProperty("db.url"),p.getProperty("db.username"),p.getProperty("db.password"));}catch(IOException e){throw new SQLException(e);}}}